stage_a_raw:
{
  "decisions": [
    {
      "decision": "domain_of_start_times",
      "evidence": "\"All operation start times must be non-negative\"",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.7,
        0.3
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "makespan_definition",
      "evidence": "\"The makespan must be at least as long as the completion time of the last operation across all jobs\"",
      "options": [
        "makespan >= start[j,o] + duration for all tasks",
        "makespan >= start[j,o] for all tasks (completion ignored)"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "makespan >= start[j,o] + duration for all tasks"
    },
    {
      "decision": "big_M_value",
      "evidence": "\"A large constant (100000) is used in the constraints\"",
      "options": [
        "big_M = 100000",
        "big_M = sum of all durations (tight bound)"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "big_M = 100000"
    },
    {
      "decision": "machine_disjunction_orientation",
      "evidence": "\"if Operation 0 of Job 0 is scheduled before Operation 0 of Job 1 on Machine 1, the binary variable X is set to 1\"",
      "options": [
        "X=1 means first task precedes second task",
        "X=1 means second task precedes first task"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "X=1 means first task precedes second task"
    },
    {
      "decision": "objective_sense",
      "evidence": "\"The goal is to minimize the total production time, known as the makespan\"",
      "options": [
        "minimize makespan",
        "maximize makespan"
      ],
      "plausibility": [
        0.99,
        0.01
      ],
      "majority_option": "minimize makespan"
    },
    {
      "decision": "precedence_constraint_direction",
      "evidence": "\"Each operation within a job must start only after the previous operation in the same job is completed\"",
      "options": [
        "start[j,o+1] >= start[j,o] + duration",
        "start[j,o+1] >= start[j,o] (duration ignored)"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "start[j,o+1] >= start[j,o] + duration"
    }
  ]
}
